    tut: {"tutTitle": "Tutorial · Lektion {n} von 3", "tutSub": ["Hinweise lesen", "Ein Duell gegen einen Bot", "Boni und Fallen"], "tutLocked": "🔒 nach den Lektionen 1–2", "gateText": "🔒 Freunde öffnen sich nach zwei kurzen Lektionen (etwa 3 Minuten): Hinweise lesen und gegen einen Gegner spielen.", "gateGo": "🎓 Lektion {n} starten", "gateSkip": "Tutorial überspringen", "coach": {"1": ["🎓 Ich habe eine Zahl von 1 bis 20 gewählt. Gib eine Zahl ein und drücke „Prüfen“.", "Der Hinweis sagt, wie nah du bist: 🔥 heiß — nah, ❄️ kalt — weit weg. Versuch eine andere Zahl.", "Die Linie unter dem Thermometer merkt sich alle Züge. Such zwischen ihnen — das geht schneller."], "2": ["🎓 Jetzt ein Duell gegen einen Bot: ihr zieht abwechselnd. Wer die Zahl zuerst nennt, gewinnt.", "Die Züge des Bots sind auch Hinweise: achte auch auf sein „heiß / kalt“.", "⚡ „+1 Zug“: zwei Züge hintereinander. Drück sie vor deinem Zug, wenn du nah dran bist."], "3": ["🎓 Auf der Linie sind Boni 🎁 versteckt. Tritt darauf und er wirkt: gute treffen den Gegner, Fallen treffen dich.", "❓ „Etwas ist in der Nähe“ — ein Bonus liegt nah. Riskieren oder umgehen — du entscheidest.", "Ein Bonus hat gewirkt! Was er tut, steht auf der Karte. Spiel weiter."]}, "lessonDone": "🎓 Lektion {n} geschafft!", "lessonOpen": "🔓 Freunde sind offen", "tutAllDone": "Tutorial geschafft! Dein 🎓-Symbol ist im Profil.", "lessonNext": "🎓 Lektion {n}", "lessonFinish": "🎓 Fertig", "tutReplay": "🎓 Tutorial wiederholen", "bcTitle": "Neuer Bonus: {name}", "bcNear": "❓ Etwas ist in der Nähe", "bcOk": "Verstanden", "bcDesc": {"div3": "Wer drauftritt, erfährt, ob die geheime Zahl durch 3 teilbar ist. Tipp: Dann ist auch ihre Quersumme durch 3 teilbar.", "div5": "Wer drauftritt, erfährt, ob die geheime Zahl durch 5 teilbar ist — also ob sie auf 0 oder 5 endet.", "compass": "Wer drauftritt, erfährt, ob die geheime Zahl größer oder kleiner als diese ist.", "thief": "Wer drauftritt, nimmt dem Gegner einen „⚡ +1 Zug“ weg. Hat der keinen, gibt es einen aus dem Vorrat.", "mirror": "Wer drauftritt, bekommt einen Spiegel: Die nächste Falle trifft den Gegner. Im Abenteuer wirft der Spiegel auch die Tricks des Gegners zurück.", "tens": "Wer drauftritt, erfährt die Zehnerziffer der geheimen Zahl: bei 47 ist es 4. Nur im Kampf gegen einen Boss.", "units": "Wer drauftritt, erfährt die letzte Ziffer der geheimen Zahl: bei 47 ist es 7. Nur im Kampf gegen einen Boss.", "xray": "Wer drauftritt, erfährt, ob die geheime Zahl gerade oder ungerade ist. Es steht neben dem Namen.", "half": "Wer drauftritt, erfährt, ob die Zahl in der unteren oder oberen Hälfte liegt.", "shield": "Wer drauftritt, bekommt einen Schild: Die nächste Falle wirkt nicht. Im Abenteuer wehrt er auch die Tricks des Gegners ab.", "freeze": "Der Gegner friert ein und setzt den nächsten Zug aus.", "extra": "Wer darauf tritt, bekommt „⚡ +1 Zug“ ×2. „+1 Zug“ gibt zwei Züge hintereinander.", "fog": "Nebel legt sich auf den Gegner: bis zum Rundenende sieht er die Züge des anderen nicht.", "blind": "Blindheit legt sich auf den Gegner: bis zum Rundenende sieht er seine eigenen Züge nicht.", "lava": "Der nächste Zug des Gegners geschieht von selbst: eine Zufallszahl nahe an der geheimen. Der Hinweis dazu hilft dem, der danach zieht.", "skip": "Eine Falle: wer darauf tritt, setzt den nächsten Zug aus.", "gift": "Eine Falle: wer darauf tritt, schenkt dem Gegner „⚡ +1 Zug“.", "memory": "Eine Falle: wer darauf tritt, sieht bis zum Rundenende nur die letzten zwei Züge.", "near": "Ein paar Schritte von deiner Zahl liegt ein Bonus — gut oder Falle. Riskieren oder umgehen — du entscheidest.", "rush": "Der Gegner kommt in Eile: 3 Sekunden weniger für jeden seiner Züge. Wirkt in Partien mit Freunden auf zwei Handys, wo der Zug eine Uhr hat."}, "tutIconLocked": "Öffnet sich nach dem Tutorial", "menuSub": {"run": "Runden am Stück — wie weit kommst du?", "solo": "Allein", "duel": "Zu zweit an einem Handy", "adv": "50 Gegner"}},
